const IBW={Devine:(s,cm)=>{const i=cm/2.54-60;return s==='M'?50+2.3*i:45.5+2.3*i},Hamwi:(s,cm)=>{const i=cm/2.54-60;return s==='M'?48+2.7*i:45.5+2.2*i},Robinson:(s,cm)=>{const i=cm/2.54-60;return s==='M'?52+1.9*i:49+1.7*i},Miller:(s,cm)=>{const i=cm/2.54-60;return s==='M'?56.2+1.41*i:53.1+1.36*i},Lorentz:(s,cm)=>s==='M'?cm-100-(cm-150)/4:cm-100-(cm-150)/2.5};
const IBWF={Devine:'M: 50 + 2.3 × (pulgadas sobre 60) · F: 45.5 + 2.3 × (pulgadas sobre 60)',Hamwi:'M: 48 + 2.7 × (pulgadas sobre 60) · F: 45.5 + 2.2 × (pulgadas sobre 60)',Robinson:'M: 52 + 1.9 × (pulgadas sobre 60) · F: 49 + 1.7 × (pulgadas sobre 60)',Miller:'M: 56.2 + 1.41 × (pulgadas sobre 60) · F: 53.1 + 1.36 × (pulgadas sobre 60)',Lorentz:'M: T − 100 − (T − 150)/4 · F: T − 100 − (T − 150)/2.5 (T = talla en cm)'};
