const SCH={M:[[3,59.512,-30.4],[10,22.706,504.3],[18,17.686,658.2],[30,15.057,692.2],[60,11.472,873.1],[999,11.711,587.7]],F:[[3,58.317,-31.1],[10,20.315,485.9],[18,13.384,692.6],[30,14.818,486.6],[60,8.126,845.6],[999,9.082,658.5]]};
const r1=x=>Math.round(x*10)/10,r0=Math.round,r2=x=>Math.round(x*100)/100;
function ger(m,v){const{sex:s,age:a,w,h}=v,M=s==='M';
if(m==='Schofield'){const b=SCH[s].find(x=>a<x[0]);return{kcal:b[1]*w+b[2],f:`${b[1]} × peso ${b[2]<0?'−':'+'} ${Math.abs(b[2])} (banda de edad correspondiente)`,ref:R.sch,adult:false,pob:'según la banda de edad y el sexo (solo peso)'}}
if(a<18)throw new UErr('Esta fórmula es para adultos (18 años o más). Para menores de 18 años usa Schofield en «Fórmulas por etapa de vida».');
if(m==='Mifflin-St Jeor')return{kcal:10*w+6.25*h-5*a+(M?5:-161),f:`10 × peso + 6.25 × talla − 5 × edad ${M?'+ 5':'− 161'} (versión simplificada publicada en el mismo artículo)`,ref:R.mif,pob:'498 adultos sanos de 19 a 78 años'};
if(m==='Mifflin-St Jeor (ecuación original)')return{kcal:9.99*w+6.25*h-4.92*a+166*(M?1:0)-161,f:'9.99 × peso + 6.25 × talla − 4.92 × edad + 166 × sexo − 161 (sexo: hombre = 1, mujer = 0)',ref:R.mif,pob:'498 adultos sanos de 19 a 78 años'};
if(m==='Harris-Benedict')return{kcal:M?66.4730+13.7516*w+5.0033*h-6.7550*a:655.0955+9.5634*w+1.8496*h-4.6756*a,f:M?'66.4730 + 13.7516 × peso + 5.0033 × talla − 6.7550 × edad':'655.0955 + 9.5634 × peso + 1.8496 × talla − 4.6756 × edad',ref:R.hb,pob:'personas de 15 a 74 años (estudio de 1919); sobrestima el gasto en poblaciones actuales'};
if(m==='Harris-Benedict (revisada 1984)')return{kcal:M?88.362+13.397*w+4.799*h-5.677*a:447.593+9.247*w+3.098*h-4.330*a,f:M?'88.362 + 13.397 × peso + 4.799 × talla − 5.677 × edad':'447.593 + 9.247 × peso + 3.098 × talla − 4.330 × edad',ref:R.hb2,pob:'revisión de Roza y Shizgal con datos de Harris y Benedict'};
if(m==='Owen')return{kcal:M?879+10.2*w:795+7.18*w,f:M?'879 + 10.2 × peso':'795 + 7.18 × peso',ref:R.owen,pob:'adultos'};
if(m==='Katch-McArdle'||m==='Mifflin-St Jeor (masa libre de grasa)'){if(v.fat==null)throw new UErr('Falta ingresar el porcentaje de grasa corporal para usar esta fórmula.');if(v.fat>=100)throw new UErr('El porcentaje de grasa debe ser menor que 100.');const mlg=w*(1-v.fat/100),ex=['Masa libre de grasa',r1(mlg),'kg'];return m==='Katch-McArdle'?{kcal:370+21.6*mlg,f:'370 + 21.6 × masa libre de grasa (kg)',ref:R.kat,extra:ex,pob:'adultos; depende de una buena estimación de la grasa corporal'}:{kcal:19.7*mlg+413,f:'19.7 × masa libre de grasa (kg) + 413',ref:R.mif,extra:ex,pob:'498 adultos sanos de 19 a 78 años'}}}
const AF=[['1.2','Sedentario (1.2)'],['1.375','Actividad ligera (1.375)'],['1.55','Actividad moderada (1.55)'],['1.725','Actividad intensa (1.725)'],['1.9','Actividad muy intensa (1.9)']];
const FM=['Mifflin-St Jeor','Mifflin-St Jeor (ecuación original)','Mifflin-St Jeor (masa libre de grasa)','Harris-Benedict','Harris-Benedict (revisada 1984)','Owen','Katch-McArdle','Schofield'];
function energia(v,m,extraRows=[]){const g=ger(m,v),rows=[['Fórmula',m,''],['Metabolismo basal (GER)',r0(g.kcal),'kcal/día']];if(g.extra)rows.push(g.extra);let get=g.kcal;
if(v.af){get=g.kcal*v.af;rows.push(['Factor de actividad',v.af,''],['Gasto energético total (GER × FA)',r0(get),'kcal/día'])}
if(v.tef){const t=get*v.tef/100;rows.push(['Efecto térmico de los alimentos ('+v.tef+'%)',r0(t),'kcal/día'],['Requerimiento estimado (GET + ETA)',r0(get+t),'kcal/día'])}
return{rows:rows.concat(extraRows),formula:'GER = '+g.f+(v.af?'; GET = GER × factor de actividad':'')+(v.tef?'; ETA = % × GET (convención; ajústala según tu criterio)':''),ref:g.ref,interp:(g.pob?'Población de desarrollo: '+g.pob+'. ':'')+'Es una estimación poblacional; el requerimiento individual debe ajustarse con criterio profesional.',get:get}}
const AFF=[{k:'af',l:'Factor de actividad (opcional)',sel:[['','No aplicar'],...AF]},{k:'tef',l:'Efecto térmico de los alimentos (opcional)',u:'%',opt:1,lo:0,hi:20}];
