antro:{t:'Antropometría',cs:[
{t:'IMC',que:'Peso y talla',calc:'Índice de masa corporal',f:[AGE,W,H],run:v=>{const i=v.w/(v.h/100)**2,c=i<18.5?'Bajo peso':i<25?'Peso normal':i<30?'Sobrepeso':i<35?'Obesidad grado I':i<40?'Obesidad grado II':'Obesidad grado III';return{rows:[['IMC',r1(i),'kg/m²'],...(v.age>=19?[['Clasificación OMS',c,'']]:[])],formula:'IMC = peso (kg) ÷ talla (m)²',interp:v.age>=19?'Clasificación para adultos según la OMS. No valora composición corporal.':'En menores de 19 años el IMC no se clasifica con estos puntos de corte; se usan percentiles o puntaje Z.',ref:R.imc}}},
{t:'Peso ideal',que:'Sexo, talla y método',calc:'Peso corporal ideal',f:[{k:'m',l:'Método',sel:Object.keys(IBW).map(x=>[x,x])},SEX,H],run:v=>({rows:(v.m==='Lorentz'&&v.sex==='F')?[['Peso ideal (Lorentz, divisor 2.5)',r1(IBW.Lorentz('F',v.h)),'kg'],['Peso ideal (Lorentz, divisor 2)',r1(v.h-100-(v.h-150)/2),'kg']]:[['Peso ideal ('+v.m+')',r1(IBW[v.m](v.sex,v.h)),'kg']],formula:IBWF[v.m],interp:'Fórmula para adultos'+(v.h<152.4?'. Tu talla es menor de 5 pies (152.4 cm): el resultado puede no ser confiable.':'.')+(v.m==='Lorentz'&&v.sex==='F'?' ATENCIÓN: las fuentes secundarias consultadas difieren en el divisor para mujeres (2.5 o 2); no se eligió una y se muestran ambas.':''),ref:REFI[v.m]})},
{t:'Peso ajustado',que:'Sexo, peso, talla',calc:'Peso ajustado (sobrepeso/obesidad)',f:[SEX,W,H,{k:'fa',l:'Factor de ajuste (usual 0.25)',opt:1,lo:.1,hi:.5}],run:v=>{const i=IBW.Devine(v.sex,v.h),f=v.fa??.25;return{rows:[['Peso ideal (Devine)',r1(i),'kg'],['Peso ajustado',r1(i+f*(v.w-i)),'kg']],formula:`Peso ideal + ${f} × (peso real − peso ideal); peso ideal por Devine`,interp:v.w<=i?'Se usa cuando el peso real supera al ideal; aquí no lo supera.':'Útil para estimar requerimientos en personas con peso real muy superior al ideal.',ref:R.dev+' · El factor de ajuste de 0.25 es de uso común; fuente pendiente de verificar.'}}},
{t:'Peso saludable',que:'Talla',calc:'Rango de peso con IMC 18.5–24.9',f:[H],run:v=>{const m=(v.h/100)**2;return{rows:[['Peso mínimo (IMC 18.5)',r1(18.5*m),'kg'],['Peso máximo (IMC 24.9)',r1(24.9*m),'kg']],formula:'Peso = IMC × talla (m)²',interp:'Rango para adultos con IMC normal según la OMS.',ref:R.imc}}},
{t:'Cambio de peso',que:'Peso habitual, actual y tiempo',calc:'Porcentaje de cambio de peso',f:[{k:'u',l:'Peso habitual',u:'kg',lo:2,hi:300},{k:'a',l:'Peso actual',u:'kg',lo:2,hi:300},{k:'t',l:'Tiempo',sel:[['1','1 semana'],['2','1 mes'],['3','3 meses'],['4','6 meses']]}],run:v=>{const d=v.u-v.a,p=d/v.u*100,L={1:[1,2],2:[5,5],3:[7.5,7.5],4:[10,10]}[v.t],lo=p>0;return{rows:[[lo?'Pérdida de peso':d<0?'Ganancia de peso':'Sin cambio',r1(Math.abs(d)),'kg'],['Cambio porcentual',r1(Math.abs(p)),'%']],formula:'% de pérdida = (peso habitual − peso actual) ÷ peso habitual × 100',interp:lo?(p>L[1]?'Pérdida severa según Blackburn.':p>=L[0]?'Pérdida significativa según Blackburn.':'Por debajo del umbral de pérdida significativa.'):'Blackburn clasifica solo pérdida de peso.',ref:R.bla}}},
{t:'Superficie corporal',que:'Peso, talla y método',calc:'Superficie corporal',f:[{k:'m',l:'Método',sel:[['Mosteller','Mosteller'],['DuBois','DuBois']]},W,H],run:v=>{const M=v.m==='Mosteller';return{rows:[['Superficie corporal ('+v.m+')',r2(M?Math.sqrt(v.h*v.w/3600):.007184*v.w**.425*v.h**.725),'m²']],formula:M?'√(talla cm × peso kg ÷ 3600)':'0.007184 × peso^0.425 × talla^0.725',interp:'Estimación de la superficie del cuerpo.',ref:M?R.mos:R.dub}}},
{t:'Cintura-cadera',que:'Sexo, cintura y cadera',calc:'Índice cintura-cadera',f:[SEX,{k:'c',l:'Cintura',u:'cm',lo:40,hi:200},{k:'p',l:'Cadera',u:'cm',lo:50,hi:200}],run:v=>{const i=v.c/v.p,lim=v.sex==='M'?.9:.85;return{rows:[['Índice cintura-cadera',r2(i),''],['Interpretación',i>lim?'Obesidad abdominal':'Sin obesidad abdominal','']],formula:'ICC = cintura ÷ cadera',interp:`Punto de corte de la OMS: mayor de ${lim} en ${v.sex==='M'?'hombres':'mujeres'}.`,ref:R.whr}}},
{t:'Circunferencia de cintura',que:'Sexo y cintura',calc:'Riesgo por circunferencia de cintura',f:[SEX,{k:'c',l:'Cintura',u:'cm',lo:40,hi:200}],run:v=>{const M=v.sex==='M',[a,b]=M?[94,102]:[80,88],r=v.c>=b?'Riesgo sustancialmente aumentado':v.c>=a?'Riesgo aumentado':'Sin riesgo aumentado';return{rows:[['Cintura',v.c,'cm'],['Riesgo metabólico',r,'']],formula:`Puntos de corte: ≥${a} cm riesgo aumentado, ≥${b} cm sustancialmente aumentado`,interp:'Para adultos; los puntos de corte pueden variar según población.',ref:R.whr}}},
{t:'Grasa corporal (Deurenberg)',que:'Sexo, edad (7 a 83 años), peso y talla',calc:'Porcentaje de grasa corporal estimado a partir del IMC',f:[SEX,AGE,W,H],run:v=>{if(v.age<7)throw new UErr('La ecuación se desarrolló en personas de 7 a 83 años; no se calcula para menores de 7 años.');const i=v.w/(v.h/100)**2,m=v.sex==='M'?1:0,ch=v.age<=15,bf=ch?1.51*i-.7*v.age-3.6*m+1.4:1.2*i+.23*v.age-10.8*m-5.4;if(bf<=0||bf>=100)throw new UErr('El resultado queda fuera de un rango posible; revisa peso, talla y edad.');return{rows:[['IMC',r1(i),'kg/m²'],['Grasa corporal estimada',r1(bf),'%'],['Masa grasa',r1(v.w*bf/100),'kg'],['Masa libre de grasa',r1(v.w*(1-bf/100)),'kg']],formula:ch?'% grasa = 1.51 × IMC − 0.70 × edad − 3.6 × sexo + 1.4 (sexo: hombre = 1, mujer = 0; personas de 15 años o menos)':'% grasa = 1.20 × IMC + 0.23 × edad − 10.8 × sexo − 5.4 (sexo: hombre = 1, mujer = 0)',interp:'Estimación a partir del IMC (error estándar de 4.1 puntos en adultos y 4.4 en niños según el estudio original). En personas con obesidad tiende a sobrestimar la grasa. La masa libre de grasa puede usarse en Katch-McArdle.',ref:R.deu}}}]},
