const flushC=()=>{clearTimeout(sv2);kvSet('evals',evals);kvSet('segs',segs);kvSet('evAct',EVA);kvSet('sgAct',SGA)},save2=()=>{clearTimeout(sv2);sv2=setTimeout(flushC,150)};addEventListener('pagehide',flushC);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushC()});
(async()=>{evals=(await kvGet('evals'))||[];segs=(await kvGet('segs'))||[];EVA=(await kvGet('evAct'))||null;SGA=(await kvGet('sgAct'))||null;render()})();
V.clinica=()=>`<h1>Clínica</h1><div class="aviso">Herramientas de apoyo educativo y profesional. Los resultados deben ser interpretados por un profesional de la salud.</div><div class="grid">${MODS[3][1].map(m=>`<button class="tile" data-m="${esc(m[0])}"><span class="i">${m[1]}</span><b>${esc(m[0])}</b></button>`).join('')}</div>`;
V.clx=()=>{const c=CL[CLX.id],ref=ids=>ids.length?`<p class="sub"><b>Referencias:</b><br>${ids.map(i=>esc(REF2[i])).join('<br>')}</p>`:'';
return `<button class="btn ghost" data-v="clinica">← Clínica</button><h1 style="margin-top:12px">${esc(c.t)}</h1><div class="aviso">${esc(c.aviso||'Información de orientación para estudio y apoyo profesional. No sustituye las guías completas ni la indicación individual.')}</div><p class="sub">Verificación: citas conocidas, aún sin cotejar línea por línea con cada guía en línea. Confirma en la referencia antes de usar un valor.</p>${c.calc?`<p><button class="btn" data-cg="${c.calc}">${esc(c.calcLabel)}</button></p>`:''}${(c.extra||[]).map(([v,l])=>`<p><button class="btn sec" data-go="${v}">${esc(l)}</button></p>`).join('')}${c.cards.map(k=>`<details class="card" style="--g:var(--tq)"><summary><b>${esc(k.t)}</b></summary>${k.s.map(([l,x])=>Array.isArray(x)?`<p><b>${esc(l)}:</b></p><ul>${x.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`:`<p><b>${esc(l)}:</b> ${esc(x)}</p>`).join('')}${k.tabla?`<div class="scroll"><table><thead><tr>${k.tabla.h.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${k.tabla.r.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${ref(k.ref||[])}</details>`).join('')}`};
// Evaluación dietética
const FQO=['','Nunca','Menos de 1 vez/semana','1–2 veces/semana','3–4 veces/semana','5–6 veces/semana','1 vez/día','Más de 1 vez/día'];
const curEv=()=>{let e=evals.find(x=>x.id===EVA)||evals[0];if(!e){e={id:'e'+Date.now(),alias:'',fecha:today(),hor:['','','','',''],rec:[[],[],[],[],[]],notas:['','','','',''],frec:{},obj:{k:'',p:'',l:'',h:''},obs:''};evals.push(e);save2()}EVA=e.id;return e};
V.cleval=()=>{const e=curEv(),M=menuTot({menu:e.rec}),a=tt(M),o=e.obj,n=x=>Number(x)||0,miss=M.reduce((s,x)=>s+x.miss,0),pct=(c,b)=>n(b)>0?r0(c/n(b)*100)+'%':'—';
return `<h1>Evaluación dietética</h1><div class="sub">Recordatorio de 24 horas y frecuencia de consumo, comparados con objetivos. Se guarda solo en este dispositivo.</div>
<div class="card" style="--g:var(--am)"><label>Etiqueta de la evaluación (no uses nombres reales)</label><div class="two"><input data-ea value="${esc(e.alias)}" placeholder="Ej. Caso 1"><input data-ef type="date" value="${esc(e.fecha)}" aria-label="Fecha"></div><div class="two" style="margin-top:10px"><select data-esel>${evals.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.alias||x.fecha)}</option>`).join('')}</select><div style="display:flex;gap:8px"><button class="btn sec" data-enew style="flex:1">Nueva</button><button class="btn ghost" data-edel>Eliminar</button></div></div></div>
<h2>Recordatorio de 24 horas</h2>${e.rec.map((L,t)=>`<div class="card" style="--g:var(--tq)"><div class="row"><h3>${T5[t]}</h3><input data-eh="${t}" type="time" value="${esc(e.hor[t])}" style="width:130px;min-height:40px" aria-label="Horario ${T5[t]}"></div>${L.map((x,i)=>{const q=lineN(x);if(!q)return `<div class="row"><span class="err">Alimento no encontrado.</span><button class="fav" data-xd="${t},${i}">✕</button></div>`;return `<div class="row" style="margin:8px 0"><div><b>${esc(q.f.n)}</b><div class="sub">${esc(qtxt(q.f,x.n))} · ${q.k==null?'kcal no identificada':r0(q.k)+' kcal'}</div></div><div style="display:flex;align-items:center"><button class="fav" style="font-size:20px" data-xq="${t},${i},-.5" aria-label="Menos">−</button><b>${x.n}</b><button class="fav" style="font-size:20px" data-xq="${t},${i},.5" aria-label="Más">+</button><button class="fav" style="font-size:18px" data-xd="${t},${i}" aria-label="Quitar">✕</button></div></div>`}).join('')}<button class="btn ghost" data-eadd="${t}" style="width:100%">➕ Agregar alimento</button><label>Bebidas, suplementos u otros (texto libre; no suma nutrientes)</label><textarea data-en="${t}" rows="2">${esc(e.notas[t])}</textarea></div>`).join('')}
<h2>Frecuencia de consumo</h2><div class="scroll"><table><tbody>${Object.keys(COL).filter(g=>g!=='Personalizado').map(g=>`<tr><td style="border-left:8px solid ${COL[g]}">${esc(g)}</td><td><select data-efq="${esc(g)}" style="min-height:40px;padding:6px 10px">${FQO.map(f=>`<option ${f===(e.frec[g]||'')?'selected':''}>${esc(f)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>
<h2>Objetivos y comparación</h2><div class="card" style="--g:var(--am)"><div class="two">${[['k','Energía (kcal)'],['p','Proteínas (g)'],['l','Lípidos (g)'],['h','Hidratos de carbono (g)']].map(([k,l])=>`<div><label>${l}</label><input data-ek="${k}" type="text" inputmode="decimal" value="${esc(o[k])}"></div>`).join('')}</div><p><button class="btn sec" data-ecopy>Usar los totales de mi dieta activa</button></p></div>
<div class="scroll"><table><thead><tr><th>Nutrimento</th><th>Consumido</th><th>Objetivo</th><th>Adecuación</th></tr></thead><tbody>${[['Energía (kcal)',a.k,o.k],['Proteínas (g)',a.p,o.p],['Lípidos (g)',a.l,o.l],['Hidratos de carbono (g)',a.h,o.h]].map(([l,c,b])=>`<tr><td>${l}</td><td><b>${r1(c)}</b></td><td>${n(b)>0?n(b):'—'}</td><td>${pct(c,b)}</td></tr>`).join('')}</tbody></table></div>
<p class="sub">${a.k>0?`Distribución de lo consumido: proteínas ${r1(a.p*4/a.k*100)}% · lípidos ${r1(a.l*9/a.k*100)}% · hidratos ${r1(a.h*4/a.k*100)}% de la energía (factores 4-9-4).`:'Agrega alimentos al recordatorio para ver los totales.'}${miss?`<br><span class="err">⚠ ${miss} dato(s) no identificado(s) no suman en los totales.</span>`:''}<br>Adecuación = consumido ÷ objetivo × 100. No se interpreta con puntos de corte propios: valora con criterio profesional.</p>
<label>Observaciones</label><textarea data-eo rows="3">${esc(e.obs)}</textarea>`};
// Seguimiento
const curSg=()=>{let s=segs.find(x=>x.id===SGA)||segs[0];if(!s){s={id:'s'+Date.now(),alias:'',reg:[]};segs.push(s);save2()}SGA=s.id;return s};
const imcR=r=>r.h?r.w/(r.h/100)**2:null;
function chart(P){const W=640,Hh=220,m={l:48,r:14,t:14,b:30},xs=P.map(p=>p.x),ys=P.map(p=>p.y),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys),pad=(y1-y0||1)*.15,lo=y0-pad,hi=y1+pad,X=x=>m.l+(x1===x0?(W-m.l-m.r)/2:(x-x0)/(x1-x0)*(W-m.l-m.r)),Y=y=>m.t+(hi-y)/(hi-lo)*(Hh-m.t-m.b);
return `<svg viewBox="0 0 ${W} ${Hh}" style="width:100%;height:auto;background:#fff;border:1px solid var(--bd);border-radius:14px" role="img" aria-label="Gráfica de progreso"><text x="4" y="${Y(y1)+4}" font-size="12" fill="#6b7f7d">${r1(y1)}</text><text x="4" y="${Y(y0)+4}" font-size="12" fill="#6b7f7d">${r1(y0)}</text><polyline fill="none" stroke="#2f8f86" stroke-width="3" points="${P.map(p=>X(p.x)+','+Y(p.y)).join(' ')}"/>${P.map(p=>`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="5" fill="#ffe9a6" stroke="#2f8f86" stroke-width="2"><title>${esc(p.l)}: ${r1(p.y)}</title></circle>`).join('')}<text x="${m.l}" y="${Hh-8}" font-size="12" fill="#6b7f7d">${esc(P[0].l)}</text><text x="${W-m.r}" y="${Hh-8}" font-size="12" fill="#6b7f7d" text-anchor="end">${esc(P[P.length-1].l)}</text></svg>`}
V.clseg=()=>{const s=curSg(),R=s.reg.slice().sort((a,b)=>a.f<b.f?-1:1),last=R[R.length-1],MET={w:['Peso (kg)',r=>r.w],imc:['IMC (kg/m²)',imcR],c:['Cintura (cm)',r=>r.c],e:['Energía (kcal)',r=>r.e]},[ml,mf]=MET[SGM],P=R.map(r=>({x:Date.parse(r.f),y:mf(r),l:r.f})).filter(p=>p.y!=null),first=R[0];
return `<h1>Seguimiento</h1><div class="sub">Registra peso, talla y cintura en el tiempo. Se guarda solo en este dispositivo.</div>
<div class="card" style="--g:var(--am)"><label>Etiqueta (no uses nombres reales)</label><input data-sa value="${esc(s.alias)}" placeholder="Ej. Caso 1"><div class="two" style="margin-top:10px"><select data-ssel>${segs.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.alias||'Sin etiqueta')}</option>`).join('')}</select><div style="display:flex;gap:8px"><button class="btn sec" data-snew style="flex:1">Nuevo</button><button class="btn ghost" data-sdel>Eliminar</button></div></div></div>
<div class="card" style="--g:var(--tq)"><h3>Nuevo registro</h3><div class="two"><div><label>Fecha *</label><input id="sg-f" type="date" value="${today()}"></div><div><label>Peso (kg) *</label><input id="sg-w" type="text" inputmode="decimal"></div><div><label>Talla (cm)</label><input id="sg-h" type="text" inputmode="decimal" value="${last&&last.h?last.h:''}"></div><div><label>Cintura (cm)</label><input id="sg-c" type="text" inputmode="decimal"></div><div><label>Energía (kcal)</label><input id="sg-e" type="text" inputmode="decimal"></div></div><label>Observaciones</label><input id="sg-o"><div id="sgerr" class="err"></div><p><button class="btn" data-sadd style="width:100%">Guardar registro</button></p></div>
${R.length?`<div class="chips">${Object.entries(MET).map(([k,v])=>`<button class="chip ${SGM===k?'on':''}" data-sm="${k}">${v[0]}</button>`).join('')}</div>${P.length>=2?chart(P):`<p class="sub">Se necesitan al menos 2 registros con ${esc(ml)} para mostrar la gráfica.</p>`}${R.length>=2&&last.w&&first.w?`<p class="sub"><b>Cambio de peso:</b> ${r1(last.w-first.w)} kg (${r1((last.w-first.w)/first.w*100)}%) entre ${esc(first.f)} y ${esc(last.f)}.</p>`:''}
<div class="scroll"><table><thead><tr><th>Fecha</th><th>Peso</th><th>Talla</th><th>IMC</th><th>Cintura</th><th>Energía</th><th>Obs.</th><th></th></tr></thead><tbody>${R.map(r=>`<tr><td>${esc(r.f)}</td><td>${r.w}</td><td>${r.h||'—'}</td><td>${imcR(r)?r1(imcR(r)):'—'}</td><td>${r.c||'—'}</td><td>${r.e||'—'}</td><td>${esc(r.o||'')}</td><td><button class="fav" style="font-size:18px" data-srm="${s.reg.indexOf(r)}" aria-label="Eliminar registro">✕</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="sub">Aún no hay registros.</p>'}`};
// Eventos
document.addEventListener('click',e=>{const t=e.target.closest('[data-cg],[data-enew],[data-edel],[data-eadd],[data-xq],[data-xd],[data-ecopy],[data-snew],[data-sdel],[data-sadd],[data-srm],[data-sm]');if(!t)return;const D=t.dataset;
if(D.cg){CX.g=D.cg;CX.i=0;CX.out=null;CX.err='';CX.back='clx';go('calcm');return}
if('enew'in D){const n={id:'e'+Date.now(),alias:'',fecha:today(),hor:['','','','',''],rec:[[],[],[],[],[]],notas:['','','','',''],frec:{},obj:{k:'',p:'',l:'',h:''},obs:''};evals.push(n);EVA=n.id;save2();render()}
else if('edel'in D||'sdel'in D){const ev='edel'in D;if(D.sure){if(ev){evals=evals.filter(x=>x.id!==EVA);EVA=null}else{segs=segs.filter(x=>x.id!==SGA);SGA=null}save2();render();toast('Eliminado.')}else{D.sure=1;t.textContent='¿Seguro?';setTimeout(()=>{if(t.isConnected){delete t.dataset.sure;t.textContent='Eliminar'}},3000)}}
else if(D.eadd!==undefined){const ev=curEv(),ti=+D.eadd;pickFood('Agregar a '+T5[ti],f=>{ev.rec[ti].push({fid:f.id,k:null,n:1});save2();render()})}
else if(D.xq){const[a,i,d]=D.xq.split(',').map(Number),x=curEv().rec[a][i];x.n=Math.max(.5,Math.min(20,x.n+d));save2();render()}
else if(D.xd){const[a,i]=D.xd.split(',').map(Number);curEv().rec[a].splice(i,1);save2();render()}
else if('ecopy'in D){const d=cur(),a=tt(eqTot(d)),ev=curEv();if(!a.k){toast('La dieta activa aún no tiene equivalentes distribuidos.');return}ev.obj={k:String(r0(a.k)),p:String(r1(a.p)),l:String(r1(a.l)),h:String(r1(a.h))};save2();render()}
else if('snew'in D){const n={id:'s'+Date.now(),alias:'',reg:[]};segs.push(n);SGA=n.id;save2();render()}
else if(D.sm){SGM=D.sm;render()}else if(D.srm!==undefined){curSg().reg.splice(+D.srm,1);save2();render()}
else if('sadd'in D){const s=curSg(),g=i=>document.getElementById(i).value.trim().replace(',','.'),er=document.getElementById('sgerr'),f=g('sg-f'),w=Number(g('sg-w')),h=g('sg-h')?Number(g('sg-h')):null,c=g('sg-c')?Number(g('sg-c')):null,en=g('sg-e')?Number(g('sg-e')):null,E=[];
if(!/^\d{4}-\d{2}-\d{2}$/.test(f))E.push('Falta ingresar la fecha.');else if(f>today())E.push('La fecha no puede ser futura.');if(!g('sg-w'))E.push('Falta ingresar el peso para guardar el registro.');else if(isNaN(w)||w<=0)E.push('El peso debe ser un número mayor que cero.');
if(h!=null&&(isNaN(h)||h<=0))E.push('La talla debe ser un número mayor que cero.');if(c!=null&&(isNaN(c)||c<=0))E.push('La cintura debe ser un número mayor que cero.');if(en!=null&&(isNaN(en)||en<=0))E.push('La energía debe ser un número mayor que cero.');if(E.length){er.innerHTML=E.map(esc).join('<br>');return}
if(w<2||w>400)toast('Ese peso es poco habitual; verifica el dato.');if(h&&(h<45||h>230))toast('Esa talla es poco habitual; verifica el dato.');s.reg.push({f,w,h,c,e:en,o:document.getElementById('sg-o').value.trim()});save2();render();toast('Registro guardado en este dispositivo.')}});
document.addEventListener('input',e=>{const t=e.target,D=t.dataset;if(D.ea!==undefined){curEv().alias=t.value;save2()}else if(D.ef!==undefined){curEv().fecha=t.value;save2()}else if(D.eh!==undefined){curEv().hor[+D.eh]=t.value;save2()}else if(D.en!==undefined){curEv().notas[+D.en]=t.value;save2()}else if(D.eo!==undefined){curEv().obs=t.value;save2()}else if(D.sa!==undefined){curSg().alias=t.value;save2()}});
document.addEventListener('change',e=>{const t=e.target,D=t.dataset;if(D.efq!==undefined){curEv().frec[D.efq]=t.value;save2()}else if(D.esel!==undefined){EVA=t.value;save2();render()}else if(D.ssel!==undefined){SGA=t.value;save2();render()}
else if(D.ek!==undefined){const v=t.value.trim().replace(',','.');if(v!==''&&(isNaN(Number(v))||Number(v)<0)){toast('El objetivo debe ser un número mayor o igual a cero.');t.value=''}else curEv().obj[D.ek]=v;save2();render()}});

