// ---- Pediatría: puntaje Z y percentil con tablas LMS importadas (OMS/CDC). No se incluye ninguna tabla: se cargan desde archivos oficiales. ----
let LMS={};const PG={sex:'M',edad:'',peso:'',talla:'',res:null,err:'',msg:''};
(async()=>{LMS=(await kvGet('lms'))||{};render()})();
const IND={wfa:['Peso para la edad','pe','meses'],lhfa:['Talla/longitud para la edad','te','meses'],bfa:['IMC para la edad','ie','meses'],wfl:['Peso para la talla/longitud (<5 años)','pt','cm']};
const erf=x=>{const s=x<0?-1:1;x=Math.abs(x);const t=1/(1+.3275911*x);return s*(1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-x*x))};
const pctil=z=>.5*(1+erf(z/Math.SQRT2))*100;
function lmsZ(R,x,y){if(x<R[0][0]||x>R[R.length-1][0])return{err:'valor fuera del rango de la tabla ('+R[0][0]+' a '+R[R.length-1][0]+')'};const i=R.findIndex(r=>r[0]>=x),a=R[i][0]===x?R[i]:R[i-1],b=R[i],f=a===b?0:(x-a[0])/(b[0]-a[0]),L=a[1]+(b[1]-a[1])*f,M=a[2]+(b[2]-a[2])*f,S=a[3]+(b[3]-a[3])*f;return{z:L===0?Math.log(y/M)/S:(Math.pow(y/M,L)-1)/(L*S),L,M,S}}
function evalCrec(){const e=Number(String(PG.edad).replace(',','.')),w=Number(String(PG.peso).replace(',','.')),h=Number(String(PG.talla).replace(',','.')),E=[];
if(PG.edad===''||isNaN(e)||e<0)E.push('Falta ingresar la edad en meses.');else if(e>228)E.push('La edad debe ser de 0 a 228 meses (19 años).');if(PG.peso===''||isNaN(w)||w<=0)E.push('Falta ingresar el peso para realizar este cálculo.');if(PG.talla===''||isNaN(h)||h<=0)E.push('Falta ingresar la talla o longitud para realizar este cálculo.');
if(E.length){PG.err=E.join(' ');PG.res=null;return}PG.err='';const bmi=w/(h/100)**2,vals={wfa:[e,w],lhfa:[e,h],bfa:[e,bmi],wfl:[h,w]},out=[];
Object.entries(IND).forEach(([k,[nom,cls,ejex]])=>{const t=LMS[k+'|'+PG.sex];if(!t){out.push({nom,pend:'Tabla LMS no cargada (pendiente)'});return}const[x,y]=vals[k],r=lmsZ(t.rows,x,y);if(r.err){out.push({nom,t,err:r.err});return}
let cl='';if(t.tipo==='OMS'){try{cl=CG.ped.cs[0].run({g:e<60?'u':'m',i:cls,z:r.z}).rows[1][1]}catch(er){cl=er.message}}else cl='La clasificación con puntos de corte OMS no se aplica a tablas '+t.tipo+'.';out.push({nom,t,y,z:r.z,p:pctil(r.z),cl,raw:Math.abs(r.z)>3})});PG.res={bmi,out,e}}
const nmx=s=>String(s).trim().toLowerCase();
function parseLMS(rows,sexo){const H=rows[0].map(nmx),ix=n=>H.findIndex(h=>n.test(h)),xi=ix(/^(month|agemos|age|length|height|len|ht|edad|mes|talla|longitud)/),li=H.indexOf('l'),mi=H.indexOf('m'),si=H.indexOf('s'),sx=ix(/^sex/),miss=[];
if(xi<0)miss.push('edad (Month/Agemos) o talla (Length/Height)');if(li<0)miss.push('L');if(mi<0)miss.push('M');if(si<0)miss.push('S');if(miss.length)throw new Error('Faltan columnas: '+miss.join(', ')+'. Columnas encontradas: '+rows[0].join(', ')+'.');
const out=[];rows.slice(1).forEach((r,i)=>{if(sx>=0){const v=nmx(r[sx]);if(!(v===(sexo==='M'?'1':'2')||v===nmx(sexo)||v===(sexo==='M'?'male':'female')||v===(sexo==='M'?'boys':'girls')))return}const v=[xi,li,mi,si].map(k=>Number(String(r[k]).replace(',','.')));if(r.every(c=>String(c).trim()===''))return;if(v.some(isNaN))throw new Error('Fila '+(i+2)+': hay valores que no son numéricos.');if(v[2]<=0||v[3]<=0)throw new Error('Fila '+(i+2)+': M y S deben ser mayores que cero.');out.push(v)});
if(out.length<10)throw new Error('La tabla tiene muy pocas filas ('+out.length+'). Revisa el archivo y el sexo elegido.');for(let i=1;i<out.length;i++)if(out[i][0]<=out[i-1][0])throw new Error('La primera columna debe ir en orden ascendente sin repetidos (fila '+(i+2)+').');return out}
V.crec=()=>{const L=Object.values(LMS);return `<button class="btn ghost" data-v="clx">← Pediatría</button><h1 style="margin-top:12px">Evaluación del crecimiento</h1><div class="aviso">nutríC <b>no incluye</b> las tablas LMS de la OMS ni del CDC. Para calcular puntaje Z y percentil, carga abajo las tablas oficiales (archivos con columnas L, M y S). Sin tabla, el indicador queda como pendiente y no se estima.</div>
<div class="card" style="--g:var(--am)"><div class="two"><div><label>Sexo</label><select data-pgs><option value="M" ${PG.sex==='M'?'selected':''}>Niño</option><option value="F" ${PG.sex==='F'?'selected':''}>Niña</option></select></div><div><label>Edad (meses)</label><input data-pge type="text" inputmode="decimal" value="${esc(PG.edad)}"></div><div><label>Peso (kg)</label><input data-pgw type="text" inputmode="decimal" value="${esc(PG.peso)}"></div><div><label>Talla o longitud (cm)</label><input data-pgh type="text" inputmode="decimal" value="${esc(PG.talla)}"></div></div><p class="sub">Menores de 2 años: longitud acostado; mayores: talla de pie. El IMC se calcula con peso y talla.</p><p><button class="btn" data-pgrun style="width:100%">Evaluar</button></p>${PG.err?`<p class="err">${esc(PG.err)}</p>`:''}</div>
${PG.res?`<div class="card" style="--g:var(--tq)"><h3>Resultado (IMC ${r1(PG.res.bmi)} kg/m²)</h3><div class="scroll"><table><thead><tr><th>Indicador</th><th>Valor</th><th>Z</th><th>Percentil</th><th>Interpretación</th></tr></thead><tbody>${PG.res.out.map(o=>o.pend||o.err?`<tr><td>${esc(o.nom)}</td><td colspan="4"><span class="nd">${esc(o.pend||'No calculable: '+o.err)}</span></td></tr>`:`<tr><td>${esc(o.nom)}</td><td>${r2(o.y)}</td><td><b>${r2(o.z)}</b></td><td>${r1(o.p)}</td><td>${esc(o.cl)}${o.raw?' · |Z|>3: valor LMS sin el ajuste especial que aplica la OMS':''}<div class="sub">Tabla: ${esc(o.t.src)} (${esc(o.t.tipo)})</div></td></tr>`).join('')}</tbody></table></div><p class="sub"><b>Fórmula:</b> Z = ((valor ÷ M)^L − 1) ÷ (L × S); si L = 0, Z = ln(valor ÷ M) ÷ S. L, M y S se interpolan linealmente entre filas. El percentil se obtiene de la distribución normal. Los resultados dependen de las tablas que cargaste. La interpretación con puntos de corte de la OMS solo aplica a tablas OMS. Esto no es un diagnóstico: valora con criterio profesional.</p></div>`:''}
<h2>Tablas LMS cargadas (${L.length})</h2>${L.map(t=>`<div class="row card" style="--g:var(--tq)"><div><b>${esc(IND[t.ind][0])}</b> · ${t.sex==='M'?'niños':'niñas'}<div class="sub">${esc(t.src)} (${esc(t.tipo)}) · ${t.rows.length} filas de ${t.rows[0][0]} a ${t.rows[t.rows.length-1][0]} ${IND[t.ind][2]} · cargada ${esc(t.fecha)}</div></div><button class="btn ghost" data-lmsdel="${t.ind}|${t.sex}" style="min-height:40px">Quitar</button></div>`).join('')||'<p class="sub">Ninguna. Los cuatro indicadores están pendientes.</p>'}
<div class="card" style="--g:var(--am)"><h3>Cargar una tabla LMS</h3><div class="sub">Archivo .csv o .xlsx con una columna de edad (Month/Agemos) o talla (Length/Height) y las columnas L, M y S, de una fuente oficial. La fuente la indicas tú y se guarda con la tabla. Se guarda solo en este dispositivo.</div>
<label>Indicador</label><select id="lm-i">${Object.entries(IND).map(([k,v])=>`<option value="${k}">${esc(v[0])}</option>`).join('')}</select><div class="two"><div><label>Sexo de la tabla</label><select id="lm-s"><option value="M">Niños</option><option value="F">Niñas</option></select></div><div><label>Tipo</label><select id="lm-t"><option>OMS</option><option>CDC</option><option>Otra</option></select></div></div><label>Fuente (obligatoria)</label><input id="lm-f" placeholder="Ej. OMS 2006, peso para la edad, 0–5 años"><label>Archivo</label><input type="file" data-lmsfile accept=".csv,.xlsx,.xls,text/csv"><div class="err" id="lm-e">${esc(PG.msg)}</div></div>`};
document.addEventListener('click',async e=>{const t=e.target.closest('[data-pgrun],[data-lmsdel],[data-go]');if(!t)return;if(t.dataset.go){go(t.dataset.go)}else if('pgrun'in t.dataset){evalCrec();render()}else{delete LMS[t.dataset.lmsdel.replace('|','|')];await kvSet('lms',LMS);render()}});
document.addEventListener('input',e=>{const D=e.target.dataset;if(D.pge!==undefined)PG.edad=e.target.value;else if(D.pgw!==undefined)PG.peso=e.target.value;else if(D.pgh!==undefined)PG.talla=e.target.value});
