const PDOM=[['ingesta','Ingesta'],['clinico','Clínico'],['conductual','Conductual-ambiental'],['situacion','Situación nutricional']],PDL=Object.fromEntries(PDOM);
const newPes=()=>({id:'p'+Date.now(),et:'',f:today(),dom:'ingesta',p:'',cod:'',e:'',s:[],obs:'',est:'activo'});
const pesTxt=x=>`${x.p||'[Problema]'}${x.cod?' ('+x.cod+')':''} relacionado con ${x.e||'[etiología]'} evidenciado por ${x.s.length?x.s.join('; '):'[signos y síntomas]'}.`;
function pesEvidence(){const o=[],s=segs.find(x=>x.id===SGA)||segs[0];
if(s&&s.reg.length){const R=s.reg.slice().sort((a,b)=>a.f<b.f?-1:1),l=R[R.length-1],f=R[0],i=imcR(l);o.push(['Seguimiento: peso '+l.w+' kg ('+l.f+')','Peso '+l.w+' kg ('+l.f+')']);if(i)o.push(['Seguimiento: IMC '+r1(i),'IMC '+r1(i)+' kg/m² ('+l.f+')']);if(l.c)o.push(['Seguimiento: cintura '+l.c+' cm','Circunferencia de cintura '+l.c+' cm ('+l.f+')']);if(R.length>1)o.push(['Seguimiento: cambio de peso','Cambio de peso de '+r1(l.w-f.w)+' kg ('+r1((l.w-f.w)/f.w*100)+' %) entre '+f.f+' y '+l.f])}
const last={};labs.slice().sort((a,b)=>a.f<b.f?-1:1).forEach(x=>{last[x.p+'|'+(x.n||'')]=x});Object.values(last).forEach(x=>{const P=LABP.find(q=>q[0]===x.p),nm=x.p==='otro'?(x.n||'Otro'):P[1],u=x.p==='otro'?(x.u||''):P[2];o.push(['Laboratorio: '+nm+' '+x.v+' '+u,nm+' '+x.v+' '+u+' ('+x.f+')'])});
const e=evals.find(x=>x.id===EVA)||evals[0];if(e){const a=tt(menuTot({menu:e.rec})),n=v=>Number(v)||0;[['Energía','k','kcal',e.obj.k],['Proteínas','p','g',e.obj.p],['Lípidos','l','g',e.obj.l],['Hidratos de carbono','h','g',e.obj.h]].forEach(([nm,k,u,ob])=>{if(n(ob)>0&&a[k]>0)o.push(['Evaluación dietética: '+nm.toLowerCase()+' '+r0(a[k]/n(ob)*100)+' % del objetivo',nm+' consumida: '+r0(a[k])+' '+u+' ('+r0(a[k]/n(ob)*100)+' % del objetivo de '+n(ob)+' '+u+') según recordatorio de 24 horas'])})}
return o}
V.clpes=()=>{if(!PE.d)PE.d=newPes();const d=PE.d,ev=pesEvidence(),L=pes.slice().sort((a,b)=>a.f<b.f?1:-1);
return `<h1>Diagnóstico nutricional (PES)</h1><div class="sub">Redacta el diagnóstico nutricional con el formato <b>Problema</b> relacionado con <b>Etiología</b> evidenciado por <b>Signos y síntomas</b>. Se guarda solo en este dispositivo.</div>
<div class="aviso">El listado oficial de términos de diagnóstico (eNCPT) pertenece a la Academy of Nutrition and Dietetics y <b>nutríC no lo incluye</b>: escribe el término y, si tienes acceso a la terminología, su código. Un diagnóstico nutricional no es un diagnóstico médico. Usa etiquetas, no nombres de pacientes.</div>
<details class="card" style="--g:var(--am)"><summary><b>Guía para redactar un buen PES</b></summary><ul class="sub"><li><b>Problema:</b> ¿lo puede resolver o mejorar la intervención nutricional?</li><li><b>Etiología:</b> ¿es la causa raíz? ¿tu intervención la puede atender, o al menos reducir los signos y síntomas?</li><li><b>Signos y síntomas:</b> ¿son específicos y medibles? Medirlos debe indicar si el problema se resolvió o mejoró.</li><li>Los datos de la valoración deben respaldar el problema, la etiología y los signos.</li><li>Como regla general se prefieren primero los diagnósticos del dominio de ingesta, luego los clínicos y al final los conductual-ambientales; estos últimos suelen funcionar mejor como etiología.</li></ul><p class="sub">Dominios de la terminología: <b>Ingesta</b> (energía, nutrimentos, líquidos y sustancias bioactivas), <b>Clínico</b> (condiciones médicas o físicas), <b>Conductual-ambiental</b> (conocimiento, actitudes, creencias o entorno físico) y <b>Situación nutricional</b>.</p><p class="sub">Fuente: ${esc(REF2.pesacad)}</p></details>
<div class="card" style="--g:var(--tq)"><div class="two"><div><label>Etiqueta del caso</label><input data-pes="et" value="${esc(d.et)}" placeholder="Ej. Caso 1"></div><div><label>Fecha</label><input data-pes="f" type="date" value="${esc(d.f)}"></div></div>
<label>Dominio</label><select data-pes="dom">${PDOM.map(([k,v])=>`<option value="${k}" ${d.dom===k?'selected':''}>${v}</option>`).join('')}</select>
<label>Problema (término del diagnóstico nutricional) *</label><input data-pes="p" value="${esc(d.p)}" placeholder="Ej. Ingesta oral inadecuada de alimentos y bebidas"><label>Código del término (opcional)</label><input data-pes="cod" value="${esc(d.cod)}">
<label>Etiología (causa raíz) *</label><textarea data-pes="e" rows="2">${esc(d.e)}</textarea>
<label>Signos y síntomas (medibles) *</label>${d.s.map((x,i)=>`<div class="row" style="margin:4px 0"><span>• ${esc(x)}</span><button class="fav" style="font-size:18px" data-pesrm="${i}" aria-label="Quitar">✕</button></div>`).join('')||'<p class="sub">Aún no agregas signos o síntomas.</p>'}
<div class="two" style="margin-top:6px"><input id="pes-s" placeholder="Escribe un signo o síntoma"><button class="btn sec" data-pesadd>Agregar</button></div>
${ev.length?`<label>O inserta un dato de nutríC</label><select data-pesins><option value="">Elegir dato guardado…</option>${ev.map((x,i)=>`<option value="${i}">${esc(x[0])}</option>`).join('')}</select>`:'<p class="sub">Cuando tengas seguimiento, laboratorio o evaluación dietética, podrás insertar esos datos como signos.</p>'}
<label>Observaciones</label><textarea data-pes="obs" rows="2">${esc(d.obs)}</textarea><label>Estado</label><select data-pes="est"><option value="activo" ${d.est==='activo'?'selected':''}>Activo</option><option value="resuelto" ${d.est==='resuelto'?'selected':''}>Resuelto</option></select>
<h3 style="margin-top:12px">Enunciado PES</h3><div class="card" style="--g:var(--am)" id="pes-prev">${esc(pesTxt(d))}</div><div class="err">${esc(PE.msg)}</div><div class="two"><button class="btn" data-pessave>Guardar diagnóstico</button><button class="btn ghost" data-pesnew>Limpiar</button></div></div>
<h2>Diagnósticos guardados (${pes.length})</h2>${L.map(x=>`<article class="card" style="--g:${x.est==='resuelto'?'#cfe8e4':'var(--tq)'}"><div class="row"><div><span class="badge ok">${esc(PDL[x.dom]||x.dom)}</span> <span class="badge">${x.est==='resuelto'?'Resuelto':'Activo'}</span><div class="sub">${esc(x.f)}${x.et?' · '+esc(x.et):''}</div></div></div><p>${esc(pesTxt(x))}</p>${x.obs?`<div class="sub">${esc(x.obs)}</div>`:''}<div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn ghost" style="min-height:40px" data-pesedit="${x.id}">Editar</button><button class="btn ghost" style="min-height:40px" data-pestog="${x.id}">Marcar ${x.est==='resuelto'?'activo':'resuelto'}</button><button class="btn ghost" style="min-height:40px" data-pesdel="${x.id}">Eliminar</button></div></article>`).join('')||'<p class="sub">Aún no hay diagnósticos guardados.</p>'}${pes.length?'<p><button class="btn ghost" data-pdf="pes">Descargar PDF</button></p>':''}`};
const pesSave=()=>kvSet('pes',pes);
document.addEventListener('click',async e=>{const t=e.target.closest('[data-pesrm],[data-pesadd],[data-pessave],[data-pesnew],[data-pesedit],[data-pestog],[data-pesdel]');if(!t)return;const D=t.dataset,d=PE.d;
if(D.pesrm!==undefined){d.s.splice(+D.pesrm,1);render()}
else if('pesadd'in D){const i=document.getElementById('pes-s'),v=i.value.trim();if(!v){toast('Escribe el signo o síntoma antes de agregarlo.');return}d.s.push(v);render()}
else if('pesnew'in D){PE.d=newPes();PE.msg='';render()}
else if('pessave'in D){const E=[];if(!d.p.trim())E.push('Falta el problema (término del diagnóstico).');if(!d.e.trim())E.push('Falta la etiología.');if(!d.s.length)E.push('Agrega al menos un signo o síntoma.');if(!/^\d{4}-\d{2}-\d{2}$/.test(d.f))E.push('Falta la fecha.');else if(d.f>today())E.push('La fecha no puede ser futura.');
if(E.length){PE.msg=E.join(' ');render();return}PE.msg='';const i=pes.findIndex(x=>x.id===d.id);if(i>=0)pes[i]=JSON.parse(JSON.stringify(d));else pes.push(JSON.parse(JSON.stringify(d)));await pesSave();PE.d=newPes();render();toast('Diagnóstico guardado en este dispositivo.')}
else if(D.pesedit){PE.d=JSON.parse(JSON.stringify(pes.find(x=>x.id===D.pesedit)));PE.msg='';render();scrollTo(0,0)}
else if(D.pestog){const x=pes.find(y=>y.id===D.pestog);x.est=x.est==='resuelto'?'activo':'resuelto';await pesSave();render()}
else if(D.pesdel){if(D.sure){pes=pes.filter(x=>x.id!==D.pesdel);await pesSave();render();toast('Diagnóstico eliminado.')}else{D.sure=1;t.textContent='¿Seguro?';setTimeout(()=>{if(t.isConnected){delete t.dataset.sure;t.textContent='Eliminar'}},3000)}}});
document.addEventListener('input',e=>{const k=e.target.dataset.pes;if(k===undefined||!PE.d)return;PE.d[k]=e.target.value;const p=document.getElementById('pes-prev');if(p)p.textContent=pesTxt(PE.d)});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.pes==='dom'||t.dataset.pes==='est'){PE.d[t.dataset.pes]=t.value}else if(t.dataset.pesins!==undefined&&t.value!==''){const x=pesEvidence()[+t.value];if(x&&!PE.d.s.includes(x[1]))PE.d.s.push(x[1]);render()}});

// ---- Micronutrientes (requerimientos NASEM/DRI) y precios: metadatos de fuente ----
