document.addEventListener('click',e=>{const t=e.target.closest('[data-mopen],[data-mt]');if(!t)return;if(t.dataset.mopen){MI.open=MI.open===t.dataset.mopen?null:t.dataset.mopen}else MI.t=t.dataset.mt;render()});
