// ---- Archivos, respaldo, importación de Excel y administración de datos ----
async function saveFile(name,data){try{const d=typeof claude!=='undefined'&&claude.use?await claude.use('downloads'):null;if(d){await d.save({filename:name,data});return true}}catch(e){if(e&&e.code==='declined')return false}
try{const a=document.createElement('a');a.href=URL.createObjectURL(data instanceof Blob?data:new Blob([data]));a.download=name;a.click();return true}catch{toast('No se pudo guardar el archivo en este navegador.');return false}}
const lib=u=>lib[u]||(lib[u]=new Promise((ok,no)=>{const s=document.createElement('script');s.src=u;s.onload=ok;s.onerror=()=>{delete lib[u];no(new Error('lib'))};document.head.append(s)}));
const SHEETJS='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js',own=f=>f.f==='Alimento personalizado',okNum=v=>v==null||(typeof v==='number'&&isFinite(v)&&v>=0);
const foodOk=f=>f&&typeof f.id==='string'&&typeof f.n==='string'&&f.n&&typeof f.g==='string'&&f.nut&&typeof f.nut==='object'&&Object.values(f.nut).every(okNum)&&okNum(f.cq)&&okNum(f.pn)&&okNum(f.pb)&&Array.isArray(f.rev||[]);
// Respaldo
async function exportBk(){const o={app:'nutriC',version:2,fecha:new Date().toISOString(),base:{fuente:'SMAE quinta edición',alimentos:BASE.length,nota:'Datos base incluidos en la app; no se exportan.'},personal:{favoritos:[...favs],alimentos_propios:custom.filter(own),alimentos_importados:custom.filter(f=>!own(f)),recetas,dietas:diets,evaluaciones:evals,seguimientos:segs,laboratorio:labs,tablas_lms:LMS,diagnosticos_pes:pes,precios}};await saveFile('nutric-respaldo-'+today()+'.json',JSON.stringify(o,null,1))}
async function importBk(file,dry){const m=document.getElementById('impmsg'),E=[],R=[];try{if(file.size>60e6)throw new Error('El archivo es demasiado grande para ser un respaldo de nutríC.');let o;try{o=JSON.parse(await file.text())}catch{throw new Error('El archivo no es un JSON válido.')}
if(!o||o.app!=='nutriC'||!o.personal||typeof o.personal!=='object')throw new Error('Este archivo no es un respaldo de nutríC.');if(![1,2].includes(o.version))throw new Error('La versión del respaldo ('+o.version+') no es compatible.');
const P=o.personal,mg=(nom,arr,list,valid)=>{if(arr==null)return;if(!Array.isArray(arr)){E.push(nom+': formato inválido, se omitió.');return}const ids=new Set(list.map(x=>x.id));let a=0,d=0,b=0;arr.forEach(x=>{if(!valid(x)){b++;return}if(ids.has(x.id)){d++;return}if(!dry)list.push(x);ids.add(x.id);a++});R.push(nom+': '+a+' nuevo(s)'+(d?', '+d+' ya existían':'')+(b?', '+b+' inválido(s) omitido(s)':''))};
mg('Alimentos propios',P.alimentos_propios,custom,foodOk);mg('Alimentos importados',P.alimentos_importados,custom,foodOk);
mg('Dietas',P.dietas,diets,x=>x&&x.id&&x.eq&&typeof x.eq==='object'&&Array.isArray(x.menu)&&x.menu.length===5);mg('Recetas',P.recetas,recetas,x=>x&&x.id&&Array.isArray(x.ing)&&x.porciones>=1);
mg('Evaluaciones',P.evaluaciones,evals,x=>x&&x.id&&Array.isArray(x.rec)&&x.rec.length===5);mg('Diagnósticos PES',P.diagnosticos_pes,pes,x=>x&&x.id&&typeof x.p==='string'&&x.p&&typeof x.e==='string'&&Array.isArray(x.s));mg('Resultados de laboratorio',P.laboratorio,labs,x=>x&&x.id&&x.p&&typeof x.v==='number'&&x.v>=0&&/^\d{4}-\d{2}-\d{2}$/.test(x.f));mg('Seguimientos',P.seguimientos,segs,x=>x&&x.id&&Array.isArray(x.reg)&&x.reg.every(r=>r&&/^\d{4}-\d{2}-\d{2}$/.test(r.f)&&r.w>0));
let np=0,nb=0;if(P.precios&&typeof P.precios==='object')Object.entries(P.precios).forEach(([k,v])=>{if(precios[k])return;if(v&&v.p>0&&['kg','l','pza'].includes(v.base)){if(!dry)precios[k]=v;np++}else nb++});R.push('Precios: '+np+' nuevo(s)'+(nb?', '+nb+' inválido(s) omitido(s)':''));
let nf=0;if(Array.isArray(P.favoritos))P.favoritos.forEach(x=>{if(typeof x==='string'&&!favs.has(x)){if(!dry)favs.add(x);nf++}});R.push('Favoritos: '+nf+' nuevo(s)');let nl=0,bl=0;if(P.tablas_lms&&typeof P.tablas_lms==='object')Object.entries(P.tablas_lms).forEach(([k,t])=>{if(LMS[k])return;if(t&&Array.isArray(t.rows)&&t.rows.length>=10&&t.rows.every(r=>Array.isArray(r)&&r.length===4&&r.every(Number.isFinite))&&t.src){if(!dry)LMS[k]=t;nl++}else bl++});R.push('Tablas LMS: '+nl+' nueva(s)'+(bl?', '+bl+' inválida(s) omitida(s)':''));
if(!dry)await Promise.all([kvSet('labs',labs),kvSet('lms',LMS),kvSet('pes',pes),kvSet('custom',custom),kvSet('diets',diets),kvSet('recetas',recetas),kvSet('evals',evals),kvSet('segs',segs),kvSet('precios',precios),kvSet('favs',[...favs])]);
m.innerHTML=`<p class="badge ok">${dry?'Archivo válido: no se importó nada (solo validación)':'Respaldo importado'}</p><ul class="sub">${R.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${E.map(x=>`<p class="err">${esc(x)}</p>`).join('')}<p class="sub">Tus datos actuales no se borran: el respaldo solo agrega lo que falta.</p>`;if(!dry)setTimeout(render,2500)}catch(e){m.innerHTML=`<p class="err">${esc(e.message||'No se pudo leer el archivo.')} No se importó nada.</p>`}}
const standalone=()=>{try{return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}catch{return false}};
