document.addEventListener('click',async e=>{const t=e.target.closest('[data-wipe]');if(!t)return;if(!t.dataset.sure){t.dataset.sure=1;t.textContent='¿Seguro? Esto no se puede deshacer';setTimeout(()=>{if(t.isConnected){delete t.dataset.sure;t.textContent='Borrar todos mis datos de este dispositivo'}},4000);return}custom=[];diets=[];recetas=[];evals=[];segs=[];labs=[];pes=[];precios={};LMS={};favs=new Set();act=null;await Promise.all(['custom','diets','recetas','evals','segs','labs','pes','precios','lms'].map(k=>kvSet(k,k==='precios'||k==='lms'?{}:[])).concat([kvSet('favs',[]),kvSet('dietAct',null)]));render();toast('Datos locales borrados.')});
